// Axles, body, cabin, headlights and wheels, in that order.
pub const MATERIAL_COUNT: u32 = 5;

const fn vertex(position: [f32; 3], normal: [f32; 3], material_index: u32) -> Vertex {
    Vertex {
        position,
        normal,
        material_index,
    }
}

